contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 d) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(d > 0 && d < type(uint256).max / 2);
        require(address(this).balance >= d);

        uint256 testBefore = address(this).balance;
        uint256 cBefore = address(c).balance;

        c.deposit{value: d}(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted && address(this).balance == testBefore && address(c).balance == cBefore);
    }

    receive() external payable {}
}

