// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 d) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(d > 0 && d < type(uint256).max / 2);
        vm.assume(address(this).balance >= d);
        uint256 testBefore = address(this).balance;
        uint256 cBefore = address(c).balance;
        try c.deposit{value: d}() {} catch { return; }
        bool reverted;
        try c.refund() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && address(this).balance == testBefore && address(c).balance == cBefore);
    }

    function testFuzz_run(uint256 d) public {
        _run(d);
    }

    receive() external payable {}
}
